[
  {
    "text": "Empirically measure whether retrieval errors from incomplete document-level metadata persist when item-level metadata is artificially completed for all items in a test corpus.",
    "topic": "document metadata vs item metadata independence"
  },
  {
    "text": "Isolate cross-document dependency errors (e.g., missing inter-document links, contradictory facts across documents) and check if these errors disappear when item-level metadata is fully provided but document-level metadata remains incomplete.",
    "topic": "cross-document dependency failure independence"
  },
  {
    "text": "Compare the sets of retrieval errors attributable to (a) missing item-level metadata, (b) incomplete document-level metadata, and (c) cross-document dependency gaps to determine if they form non-overlapping failure modes.",
    "topic": "error mode overlap analysis"
  },
  {
    "text": "Evaluate whether any cross-document dependency gap can be resolved by enriching item-level metadata (e.g., adding cross-reference fields to item records) without altering document-level metadata.",
    "topic": "mitigation by item metadata"
  }
]
